/* PCG STATLAB — created by theMadaa. Local-first study UI; optional authenticated cloud sync. */
'use strict';
const COURSE=window.STAT_COURSE, CH=COURSE.chapters, $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const NAV=[['home','⌂','Overview'],['plan','◷','Revision roadmap'],['labs','◈','Interactive labs'],['practice','◉','Practice & mock exam'],['calculator','∑','Formula calculator'],['formulas','▤','Formula library']];
const defaults={theme:'dark',completed:[],bookmarks:[],notes:{},lessonAnswers:{},quizMode:'all',quizAnswers:{},quizSubmitted:false,quizItems:[],focus:false,studySessions:0,quizDeadline:0};
let state={...defaults};try{let s=JSON.parse(localStorage.getItem('PCG_STATLAB_STATE')||'{}');state={...defaults,...s};}catch(_){ }
let currentRoute='',sourceFiles=[],activeSource=-1,sourcePage=1,sourceQuery='',calculatorMode='mean-z',labMode='normal',quizTimer=null,quizEnd=0;
function save(){try{localStorage.setItem('PCG_STATLAB_STATE',JSON.stringify(state))}catch(_){};window.PCGCloud?.onLocalSave?.(state)}
function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function route(){return decodeURIComponent(location.hash.replace(/^#/,'')||'home')}
function go(path){if(location.hash!=='#'+path)location.hash=path;else render()}
function badge(t,solid=false){return `<span class="mini-pill ${solid?'solid':''}">${esc(t)}</span>`}
function toast(t){let a=$('#toast');a.textContent=t;a.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>a.classList.remove('show'),2400)}
function iconDone(id){return state.completed.includes(id)?'✓':'→'}
function miniRefresh(){let p=Math.round(state.completed.length/CH.length*100);$('#courseProgressMini').textContent=p+'%';$('#miniProgressFill').style.width=p+'%'}
function sidebar(){const r=route();$('#mainNav').innerHTML=NAV.map(([id,ic,name])=>`<button data-go="${id}" class="nav-item ${r.split('/')[0]===id?'active':''}"><span class="ni">${ic}</span>${esc(name)}</button>`).join('');$('#moduleNav').innerHTML=CH.map((c,i)=>`<button class="module-item ${r===('lesson/'+c.id)?'active':''}" data-go="lesson/${c.id}"><span class="index">${String(i).padStart(2,'0')}</span><span>${esc(c.title.replace(/^\d+ · /,''))}</span><span class="check">${state.completed.includes(c.id)?'✓':''}</span></button>`).join('');miniRefresh()}
function header(ey,title,desc){return `<div class="eyebrow">${esc(ey)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-desc">${esc(desc)}</p>`}
function head2(name,aside=''){return `<div class="section-head"><div><span class="section-kicker">LEARN / EXPLORE</span><h2>${esc(name)}</h2></div>${aside}</div>`}
function moduleCard(c,i){return `<button class="module-card" data-go="lesson/${c.id}"><div class="module-top"><span>${esc(c.tag)} · ${String(i+1).padStart(2,'0')}</span><span class="bookmark-icon ${state.completed.includes(c.id)?'on':''}">${iconDone(c.id)}</span></div><h3>${esc(c.title.replace(/^\d+ · /,''))}</h3><p>${esc(c.summary.slice(0,116))}${c.summary.length>116?'…':''}</p><div class="module-foot"><span>${c.minutes} MIN · ${c.concepts.length} CONCEPTS</span><span class="arrow-circle">↗</span></div></button>`}
function home(){const done=state.completed.length;const curr=CH.find(c=>!state.completed.includes(c.id))||CH[0];return `<section class="hero"><div class="hero-copy"><div class="tag-row">${badge('WAYAMBA · STAT 2112',true)}${badge('BEGINNER → EXAM READY')}</div><h1>Statistics.<br/><em>Finally,</em><br/>understand it.</h1><p>කවදාවත් Stats ඉගෙන නොගත්ත කෙනෙක්ටත් තේරෙන විදිහට. First concepts → visual intuition → step-by-step calculations → exam practice. No blind memorizing.</p><div class="hero-actions"><button class="btn" data-go="lesson/${curr.id}">${done?'Continue learning':'Start from zero'} <span>↗</span></button><button class="btn secondary" data-go="labs">Explore simulations ↗</button></div></div><div class="hero-art"><canvas id="heroCanvas"></canvas><div class="crosshair">⌁</div><span class="plane-label">PROBABILITY / IN 3D</span></div></section><div class="stats-grid"><div class="stat-card"><div class="stat-label">COURSE TOPICS</div><div class="stat-value">${CH.length}</div><div class="stat-foot">lecture + prerequisite + preview</div></div><div class="stat-card"><div class="stat-label">WORKED EXAMPLES</div><div class="stat-value">${CH.reduce((s,c)=>s+c.examples.length,0)}</div><div class="stat-foot">step-by-step solved</div></div><div class="stat-card"><div class="stat-label">YOUR PROGRESS</div><div class="stat-value">${Math.round(done/CH.length*100)}%</div><div class="stat-foot">${done} of ${CH.length} chapters finished</div></div><div class="stat-card"><div class="stat-label">LEARNING TOOLS</div><div class="stat-value">5</div><div class="stat-foot">interactive visual labs</div></div>${head2('Your recommended learning path','<button class="small-link" data-go="plan">View 4-day revision roadmap →</button>')}<div class="module-grid">${CH.filter(c=>!state.completed.includes(c.id)).slice(0,6).map((c)=>moduleCard(c,CH.indexOf(c))).join('')||CH.slice(0,6).map((c)=>moduleCard(c,CH.indexOf(c))).join('')}</div>${state.bookmarks.length?head2('Your saved chapters')+'<div class="module-grid">'+CH.filter(c=>state.bookmarks.includes(c.id)).map(c=>moduleCard(c,CH.indexOf(c))).join('')+'</div>':''}${head2('Built to make concepts click')}<div class="lab-grid"><button class="lab-card" data-go="labs/normal"><span class="eyebrow">01 / 2D LAB</span><h3>Probability distribution explorer ↗</h3><p>Move threshold z, change distribution; see area/probability update.</p><span class="module-foot">NORMAL · t · χ² · F</span></button><button class="lab-card" data-go="labs/3d"><span class="eyebrow">02 / 3D LAB</span><h3>3D probability surface ↗</h3><p>Drag the interactive surface to understand how a 2-variable bell shape behaves.</p><span class="module-foot">DRAG TO ROTATE</span></button><button class="lab-card" data-go="labs/sampling"><span class="eyebrow">03 / SIMULATION</span><h3>95% confidence in action ↗</h3><p>Run independent sampling experiments; watch intervals hit or miss the unknown mean.</p><span class="module-foot">REPEATED-SAMPLING VIEW</span></button></div><div class="section-head"><div><span class="section-kicker">LOCAL FIRST / OPTIONAL CLOUD SYNC</span><h2>Study progress backup</h2></div></div><div class="button-row"><button class="btn secondary" data-action="export-progress">↧ Export progress JSON</button><label class="btn secondary" style="cursor:pointer">↥ Import progress <input type="file" id="importProgress" accept="application/json,.json" style="display:none" /></label><button class="btn secondary" data-action="reset-progress">Reset local progress</button></div><div class="source-note"><strong>Source transparency:</strong> Chapters 04–18 are grounded in the provided lecture handouts, whereas maths rescue chapters add prerequisites. Hypothesis Testing (19–20) is an introductory syllabus-based extension because the detailed lecture handouts for those units were not attached. Original source PDFs are preserved and available in the library.</div>`}
function lesson(id){let c=CH.find(c=>c.id===id);if(!c)return notFound();let i=CH.indexOf(c),oneQuestions=COURSE.quiz.map((q,j)=>({...q,index:j})).filter(q=>q.lesson===id);return `<section class="lesson-top"><div class="chapter-heading"><span class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')} / ${esc(c.tag)}</span><h1>${esc(c.title)}</h1><p>${esc(c.summary)}</p></div><div class="lesson-tools"><button class="lesson-tool ${state.bookmarks.includes(id)?'on':''}" data-bookmark="${esc(id)}">${state.bookmarks.includes(id)?'★':'☆'} Save</button><button class="lesson-tool" data-action="print">⇧ Print</button></div></section><div class="chapter-meta"><span>◷ ${c.minutes} min read</span><span>◈ ${c.concepts.length} concepts</span><span>∑ ${c.examples.length} fully worked questions</span><span>☷ ${oneQuestions.length} quick checks</span></div><div class="chapter-layout"><div class="chapter-body">${c.mode!=='Core lecture'?`<div class="lesson-notice"><strong>${esc(c.mode)}</strong> — ${c.mode.startsWith('Syllabus')?'The detailed hypothesis-testing lecture handouts were not uploaded. This is supplementary introductory content based on the course outline.':c.mode.startsWith('Prerequisite')?'These prerequisites are a teaching bridge, added to make your original lecture notes understandable.':'Use the original document for exact table conventions and further detail.'}</div>`:''}<div id="concepts">${head2('Understand the concepts')} ${c.concepts.map((a,j)=>`<article class="concept-card"><div class="concept-top"><span class="concept-n">${String(j+1).padStart(2,'0')}</span><h3>${esc(a.h)}</h3></div><p>${esc(a.b)}</p><div class="formula-block">${esc(a.f)}</div><div class="concept-note"><b>↳ THINK:</b><span>${esc(a.k)}</span></div></article>`).join('')}</div><section id="examples">${head2('Worked examples',`<span class="source-pill">${c.examples.length} SOLVED</span>`)}<div class="tip-line">ඔයාම උත්සාහ කරන්න. Answer බලන්න නම් problem එක click කරන්න.</div>${c.examples.map((a,j)=>`<details class="worked-card"><summary><span><span class="faded">EX ${String(j+1).padStart(2,'0')} /</span> ${esc(a.q)}</span></summary><div class="worked-content">${a.steps.map((s,k)=>`<div class="worked-step"><span class="step-num">${k+1}</span><span>${esc(s)}</span></div>`).join('')}<div class="answer-line"><small>FINAL ANSWER</small>${esc(a.ans)}</div></div></details>`).join('')}</section><section id="quick-check">${head2('Quick concept check')}${oneQuestions.map((q,j)=>renderQuestion(q,j,true)).join('')||'<p>No quick-check question for this topic yet. Review the worked examples.</p>'}</section><div class="button-row" style="margin-top:23px"><button class="btn ${state.completed.includes(id)?'secondary':''}" data-complete="${id}">${state.completed.includes(id)?'✓ Chapter completed · Undo':'✓ Mark chapter completed'}</button><button class="btn secondary" data-go="practice">Practice all questions ↗</button></div><div class="next-prev">${i?`<button data-go="lesson/${CH[i-1].id}"><small>← PREVIOUS</small>${esc(CH[i-1].title.replace(/^\d+ · /,''))}</button>`:'<button data-go="home"><small>← PREVIOUS</small>Course overview</button>'}${i<CH.length-1?`<button data-go="lesson/${CH[i+1].id}"><small>NEXT →</small>${esc(CH[i+1].title.replace(/^\d+ · /,''))}</button>`:`<button data-go="practice"><small>NEXT →</small>Exam practice</button>`}</div></div><aside class="lesson-rail"><div class="rail-card"><h4>ON THIS PAGE</h4><a href="#concepts" class="inpage" data-scroll="concepts">01 · Understand concepts</a><a href="#examples" class="inpage" data-scroll="examples">02 · Worked examples</a><a href="#quick-check" class="inpage" data-scroll="quick-check">03 · Quick check</a></div><div class="rail-card"><h4>MY NOTES</h4><textarea id="lessonNotes" data-note="${id}" aria-label="Private study notes" placeholder="Your own memory tricks, questions, formulas…">${esc(state.notes[id]||'')}</textarea><p class="tiny">Saved locally, and on your account when cloud sync is enabled.</p></div><div class="rail-card"><h4>LECTURE SOURCE</h4><div class="tiny">Original course handouts are available in the private offline package only.</div></div></aside></div>`}
function renderQuestion(q,j,inline){let key=(inline?'lesson:':'practice:')+q.index;let sel=inline?state.lessonAnswers[key]:state.quizAnswers[key];let revealed=inline?sel!==undefined:state.quizSubmitted;return `<article class="quiz-question" data-q="${q.index}"><div class="quiz-top"><span>${inline?'CHECK YOUR UNDERSTANDING':'QUESTION '+String(j+1).padStart(2,'0')}</span><span>${esc(CH.find(c=>c.id===q.lesson)?.tag||'')}</span></div><h3>${esc(q.q)}</h3><div class="quiz-answers">${q.opts.map((o,k)=>`<button ${revealed?'disabled':''} data-qchoice="${q.index}" data-inline="${inline?'1':'0'}" data-choice="${k}" class="${sel===k?'picked':''} ${revealed&&k===q.correct?'correct':''} ${revealed&&sel===k&&k!==q.correct?'wrong':''}"><b>${String.fromCharCode(65+k)}.</b> ${esc(o)}</button>`).join('')}</div>${revealed?`<div class="quiz-explanation"><b>${sel===q.correct?'✓ Correct':'→ Correct answer: '+String.fromCharCode(65+q.correct)}</b><div>${esc(q.explain)}</div></div>`:''}</article>`}
function labs(){return `${header('INTERACTIVE VISUAL LABORATORY','See the mathematics.','Move sliders, rotate a 3D surface, simulate experiments and watch every value update in real time. All simulations run locally in your browser.')}<div class="lab-grid" style="margin-top:24px">${[['normal','↗','Distribution explorer','Normal, t, χ² and F area models.'],['3d','◈','3D density landscape','Rotatable, parameter-controlled probability surface.'],['sampling','◉','Confidence interval simulation','Repeated intervals, coverage and uncertainty.'],['integral','∫','Integration area lab','Build integrals from rectangular strips.'],['mle','∑','Likelihood explorer','Find the p that best explains observed samples.']].map(([id,s,title,txt])=>`<button class="lab-card" data-go="labs/${id}"><span class="eyebrow">${s} LIVE SIMULATION</span><h3>${title}</h3><p>${txt}</p><span class="module-foot">OPEN LAB ↗</span></button>`).join('')}</div>`}
function lab(id){labMode=id;const names={normal:'Distribution explorer','3d':'3D probability landscape',sampling:'Confidence interval simulation',integral:'Integral area simulator',mle:'Maximum likelihood explorer'};if(!names[id])return labs();let tabs=`<div class="lab-chooser">${Object.keys(names).map(k=>`<button class="chip ${k===id?'selected':''}" data-go="labs/${k}">${esc(names[k])}</button>`).join('')}</div>`;
let content='';if(id==='normal')content=`<div class="control-panel"><div class="control-grid"><div class="field"><label>Distribution</label><select id="distKind"><option value="normal">Normal · N(0,1)</option><option value="t">Student t</option><option value="chi">Chi-square · χ²</option><option value="f">F distribution</option></select></div><div class="field"><label>Degrees of freedom 1 <b id="df1label">8</b></label><input id="distDf1" type="range" min="1" max="35" value="8" /></div><div class="field"><label>Degrees of freedom 2 <b id="df2label">12</b></label><input id="distDf2" type="range" min="1" max="35" value="12" /></div><div class="field"><label>Threshold <b id="thresholdLabel">1.00</b></label><input id="distThreshold" type="range" min="-3.5" max="4.5" step=".05" value="1" /></div></div></div><div class="visual-frame" style="margin-top:14px"><canvas id="distCanvas" aria-label="Distribution density and shaded cumulative area"></canvas><div class="visual-caption">Shaded area = P(X ≤ threshold), unshaded region is right tail. “Area under density” becomes actual probability.</div></div><div class="grid-two" style="margin-top:14px"><div class="data-box"><div class="metric-title">LEFT-TAIL AREA / CDF</div><div class="metric" id="distLeft">—</div></div><div class="data-box"><div class="metric-title">RIGHT-TAIL AREA / 1−CDF</div><div class="metric" id="distRight">—</div></div></div>`;
if(id==='3d')content=`<div class="control-panel"><div class="control-grid"><div class="field"><label>Spread σ <b id="spreadLabel">1.00</b></label><input id="spreadRange" type="range" min=".55" max="2" step=".05" value="1" /></div><div class="field"><label>Peak height <b id="heightLabel">1.00</b></label><input id="heightRange" type="range" min=".5" max="2.4" step=".05" value="1" /></div><div class="field"><label>Rotation <b id="rotationLabel">35°</b></label><input id="rotationRange" type="range" min="0" max="360" step="1" value="35" /></div><div class="field"><label>Elevation <b id="elevationLabel">38°</b></label><input id="elevationRange" type="range" min="10" max="75" step="1" value="38" /></div></div></div><div class="visual-frame tall" style="margin-top:14px"><canvas id="surfaceCanvas" aria-label="Interactive 3D bivariate normal surface"></canvas><div class="visual-caption">Drag to rotate in 3D (or use sliders). The height encodes joint density f(x,y); probability for a region requires volume below that region, not just its peak height. Shape shown is proportional to e^(−(x²+y²)/(2σ²)).</div></div>`;
if(id==='sampling')content=`<div class="control-panel"><div class="control-grid"><div class="field"><label>Sample size n <b id="sampleNLabel">25</b></label><input type="range" id="sampleN" min="4" max="100" value="25" step="1" /></div><div class="field"><label>Nominal confidence</label><select id="sampleLevel"><option value=".90">90%</option><option value=".95" selected>95%</option><option value=".99">99%</option></select></div><div class="field" style="display:flex;align-items:end"><button class="btn" data-action="sample-one">+ Draw one sample</button></div><div class="field" style="display:flex;align-items:end"><button class="btn secondary" data-action="sample-100">+ Draw 100</button></div></div><div class="button-row" style="margin-top:17px"><button class="btn small secondary" data-action="sample-clear">↺ Reset experiment</button></div></div><div class="visual-frame tall" style="margin-top:14px"><canvas id="sampleCanvas" aria-label="Sample confidence intervals with a true population mean"></canvas><div class="visual-caption">Each horizontal bar is one 95% (or selected confidence) interval. Vertical center line = true μ. Thick black/white intervals cover μ; faint dashed intervals miss it. Coverage approaches the nominal level with repeated random sampling.</div></div><div class="grid-two" style="margin-top:14px"><div class="data-box"><div class="metric-title">SIMULATIONS</div><div class="metric" id="sampleTrials">0</div></div><div class="data-box"><div class="metric-title">OBSERVED COVERAGE</div><div class="metric" id="sampleCoverage">—</div></div></div>`;
if(id==='integral')content=`<div class="control-panel"><div class="control-grid"><div class="field"><label>Upper limit b <b id="boundLabel">2.0</b></label><input id="integralBound" type="range" min=".5" max="3" value="2" step=".1" /></div><div class="field"><label>Rectangle count n <b id="rectLabel">12</b></label><input id="integralRects" type="range" min="2" max="90" value="12" step="1" /></div><div class="field"><label>Function</label><select id="integralFunction"><option value="square">f(x) = x²</option><option value="linear">f(x) = 2x</option><option value="exp">f(x) = e^(−x)</option></select></div></div></div><div class="visual-frame" style="margin-top:14px"><canvas id="integralCanvas" aria-label="Rectangle approximation to area under curve"></canvas><div class="visual-caption">Left-endpoint Riemann sum = width × sum of rectangle heights. Increase n until the rectangles approach the actual curve area.</div></div><div class="grid-two" style="margin-top:14px"><div class="data-box"><div class="metric-title">RECTANGLE APPROXIMATION</div><div class="metric" id="integralApprox">—</div></div><div class="data-box"><div class="metric-title">EXACT DEFINITE INTEGRAL</div><div class="metric" id="integralExact">—</div></div></div>`;
if(id==='mle')content=`<div class="control-panel"><div class="control-grid"><div class="field"><label>Trials n <b id="mleNLabel">10</b></label><input id="mleN" type="range" min="2" max="45" value="10" step="1" /></div><div class="field"><label>Successes k <b id="mleKLabel">7</b></label><input id="mleK" type="range" min="0" max="10" value="7" step="1" /></div></div></div><div class="visual-frame" style="margin-top:14px"><canvas id="mleCanvas" aria-label="Relative Bernoulli likelihood as function of p"></canvas><div class="visual-caption">You observed k successes out of n. Slide k to change the data. The curve shows relative likelihood L(p); the highest point gives maximum-likelihood estimate p̂=k/n. Vertical position is scaled for easy comparison.</div></div><div class="grid-two" style="margin-top:14px"><div class="data-box"><div class="metric-title">MAXIMUM LIKELIHOOD ESTIMATE</div><div class="metric" id="mleEstimate">—</div></div><div class="data-box"><div class="metric-title">MEANING</div><div id="mleMeaning" class="tip-line">—</div></div></div>`;
return `${header('INTERACTIVE LAB / '+id.toUpperCase(),names[id],id==='3d'?'Explore and rotate a live, three-dimensional statistical model.':'Change the variables. Learn with the visual, not by memorizing.')}${tabs}${content}<div class="source-note"><strong>Think like a scientist:</strong> These are interactive numerical illustrations for understanding. Formal inference additionally requires checking sampling, normality, independence and other model assumptions.</div>`}
const PLAN=[['01 · Start with the language','Maths rescue · Functions & logs · Integration · Probability','math-language,functions,integration,probability'],['02 · Understand why inference works','Inductive reasoning · Samples and statistics · Moments · Method of moments','inference,moments,mom'],['03 · Get estimation marks','MLE · Confidence interval and pivots · Normal, t, χ² and F · CI for mean','mle,ci-pivots,distributions,one-mean'],['04 · The heavy calculation chapters','CI for proportions · Difference of proportions · Two means pooled/Welch/known','one-proportion,two-proportion,two-means-pooled,two-means-welch,two-means-known'],['05 · Complete the confidence intervals','Paired observations · Population variance · Ratio of variances','paired,variance,variance-ratio'],['06 · Final exam drill','Read statistical tables · Formula chooser · Mock questions · Preview testing if included','tables,revision,tests,tests-applied']];
function plan(){return `${header('STUDY SMART, NOT LONG','Your rapid revision roadmap.','Exam එක ළඟ නම් lectures සම්පූර්ණයෙන් මුල සිට කියවීමට වඩා prerequisites අල්ලාගෙන question solving වෙත යන්න. Sessions need not match calendar days; repeat your weakest ones.')}<div class="source-note"><strong>How to use:</strong> Each session: 10 min intuition → 25–45 min worked calculations → 10 min no-notes practice. If Wednesday is your mid, prioritize the topics your lecturer explicitly included; the supplied course overview does not specify your particular mid-test coverage.</div>${head2('Six focused sessions')}<div class="planner-list">${PLAN.map((row,j)=>`<div class="planner-block"><span class="time-chip">SESSION ${String(j+1).padStart(2,'0')}</span><h3>${esc(row[0])}</h3><p>${esc(row[1])}</p><div class="plan-actions">${row[2].split(',').map(k=>`<button class="chip" data-go="lesson/${k}">${esc(CH.find(c=>c.id===k)?.title.replace(/^\d+ · /,'')||k)} ↗</button>`).join('')}</div></div>`).join('')}</div>${head2('Last-minute exam checklist')}<div class="starter-steps"><p>□ Identify the population parameter first · □ Are samples independent or paired? · □ Are variances known? · □ Choose z/t/χ²/F · □ Write degrees of freedom · □ α/2 for two-sided CIs · □ Explain interval in context · □ Verify the answer has correct sign/units.</p></div><div class="button-row" style="margin-top:18px"><button class="btn" data-go="practice">Start exam practice ↗</button><button class="btn secondary" data-go="formulas">Open formula sheet ↗</button></div>`}
function formulas(){return `${header('REFERENCE / QUICK ACCESS','Formula library.','All the high-yield equations in one searchable place. Critical-value notation here uses LOWER-TAIL quantiles unless stated otherwise.')}<div class="control-panel" style="margin-top:20px"><div class="field"><label for="formulaFilter">SEARCH FORMULAS</label><input type="search" id="formulaFilter" placeholder="Try: Welch, t, difference, variance, MLE…" /></div></div><div class="surface" style="margin-top:15px;overflow:auto"><table class="formula-table"><thead><tr><th>PARAMETER</th><th>CASE</th><th>METHOD / EQUATION</th><th>DISTRIBUTION</th></tr></thead><tbody id="formulaRows">${makeFormulaRows('')}</tbody></table></div><div class="source-note"><strong>Important:</strong> z* = z(1−α/2), t* = t(1−α/2, df), χ²upper=χ²(1−α/2,df), χ²lower=χ²(α/2,df), similarly F quantiles. χ²/F tables in the PDFs often use UPPER-TAIL notation; convert it before substituting.</div><div class="button-row" style="margin-top:18px"><button class="btn secondary" data-action="print">⇧ Print / Save as PDF</button><button class="btn secondary" data-go="calculator">Numerical calculator ↗</button></div>`}
function makeFormulaRows(q){let ff=COURSE.formulas.filter(row=>row.join(' ').toLowerCase().includes(q.toLowerCase()));return ff.map(a=>`<tr><td><strong>${esc(a[0])}</strong></td><td>${esc(a[1])}</td><td>${esc(a[2])}</td><td>${esc(a[3])}</td></tr>`).join('')||`<tr><td colspan="4">No matching formula.</td></tr>`}
function practice(){const modes=[['all','All topics'],['foundation','Prerequisites'],['lectures','Lectures only'],['mock','Timed mock · 20 Qs']];return `${header('EXAM ENGINE','Prove you understand.','Select a question set. Choose an option, then check your answers with full explanations. Use timed mock for exam-style rehearsal.')}<div class="lab-chooser">${modes.map(([id,label])=>`<button class="chip ${state.quizMode===id?'selected':''}" data-quizmode="${id}">${label}</button>`).join('')}</div><div class="button-row" style="margin:10px 0 24px"><button class="btn" data-action="new-quiz">↻ ${state.quizItems.length?'New question set':'Start practice'}</button><button class="btn secondary" data-action="reset-quiz">Clear responses</button><span class="tag-static">${state.quizMode==='mock'?'25 minutes / 20 questions': 'Self-paced · MCQ + explanations'}</span></div><div id="quizArea">${renderQuizArea()}</div>`}
function renderQuizArea(){if(!state.quizItems.length)return `<div class="lesson-notice"><strong>Ready when you are.</strong> Press “Start practice” to load your question set. Your chapter quick checks are also available inside each lesson.</div>`;let qlist=state.quizItems.map(i=>({...COURSE.quiz[i],index:i}));let n=qlist.length,answerCount=Object.keys(state.quizAnswers).filter(k=>k.startsWith('practice:')&&qlist.some(q=>('practice:'+q.index)===k)).length,score=qlist.filter(q=>state.quizAnswers['practice:'+q.index]===q.correct).length;let headerBlock=state.quizSubmitted?`<div class="score-banner" style="margin-bottom:23px"><div><span class="eyebrow">PRACTICE RESULTS</span><div><strong>${score} / ${n}</strong></div><p>${(100*score/n).toFixed(0)}% correct · Review the explanations below, then try again.</p></div><button class="btn" data-action="new-quiz">Try another set ↻</button></div>`:`<div class="score-banner" style="margin-bottom:23px"><div><span class="eyebrow">LIVE QUESTION SET</span><div><strong>${answerCount} / ${n}</strong></div><p>Answered · You can change answers until submission</p></div><div class="button-row">${state.quizMode==='mock'?'<b id="mockTimer" class="tag-static">25:00</b>':''}<button class="btn" data-action="submit-quiz">Submit answers ↗</button></div></div>`;return headerBlock+qlist.map((q,j)=>renderQuestion(q,j,false)).join('')+(!state.quizSubmitted?`<button class="btn" data-action="submit-quiz">Finish & show explanations ↗</button>`:'')}
function newQuiz(){let pool=COURSE.quiz.map((q,i)=>({q,i})).filter(x=>state.quizMode==='all'||state.quizMode==='mock'||(state.quizMode==='foundation'?['math-language','functions','integration','probability'].includes(x.q.lesson):!['math-language','functions','integration','probability','tests','tests-applied'].includes(x.q.lesson))).map(x=>x.i);
for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}state.quizItems=pool.slice(0,state.quizMode==='mock'?Math.min(20,pool.length):Math.min(15,pool.length));state.quizAnswers={};state.quizSubmitted=false;state.quizDeadline=state.quizMode==='mock'?Date.now()+25*60*1000:0;save();if(state.quizMode==='mock'){quizEnd=state.quizDeadline;startTimer()}else{clearInterval(quizTimer)}render({keep:true})}
function startTimer(){quizEnd=state.quizDeadline||quizEnd;clearInterval(quizTimer);quizTimer=setInterval(()=>{let el=$('#mockTimer');if(!el){clearInterval(quizTimer);return}let sec=Math.max(0,Math.ceil((quizEnd-Date.now())/1000));el.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec===0){clearInterval(quizTimer);if(!state.quizSubmitted){state.quizSubmitted=true;save();render({keep:true});toast('Time finished · answers submitted')}}},1000)}
function sourceLibrary(){return `${header('ORIGINAL UPLOADED MATERIAL','Your entire source library.','Every uploaded PDF is included locally. Browse the original notes, compare formulas and inspect complete page-by-page extracted text. All 110 pages, including reference tables.')}<div class="source-note"><strong>Faithful references:</strong> Complete PDF page images are the authoritative original. Extracted page text is for searching and accessibility; unusual mathematical symbols may extract imperfectly. Two duplicate normal/t table files and the duplicated Lecture 06 are retained as uploaded.</div><div class="source-cards">${sourceFiles.map((s,i)=>`<button class="source-card ${activeSource===i?'active':''}" data-opensource="${i}"><span class="paper-icon">▤</span><span><strong>${esc(s.file)}</strong><span>${s.pageCount} PAGES · PDF</span></span><span class="source-arrow">↗</span></button>`).join('')}</div><section class="source-view" id="sourceView">${activeSource<0?'<p class="faded">Select a PDF above to open the page viewer.</p>':sourceViewer()}</section>`}
function sourceViewer(){let s=sourceFiles[activeSource];if(!s)return '';const uri='notes/'+encodeURIComponent(s.file);let val=(s.pages||[])[sourcePage-1]||'';return `<div class="button-row" style="justify-content:space-between;margin-bottom:15px"><div><strong style="font-size:13px">${esc(s.file)}</strong><div class="tip-line">${s.pageCount} original pages</div></div><a class="btn secondary small" href="${uri}" target="_blank" rel="noopener">Open full PDF ↗</a></div><div class="control-grid" style="margin-bottom:12px"><div class="field"><label>PAGE</label><select id="sourcePageSelect">${s.pages.map((_,i)=>`<option value="${i+1}" ${sourcePage===i+1?'selected':''}>Page ${i+1} of ${s.pageCount}</option>`).join('')}</select></div><div class="field"><label>FIND TEXT IN CURRENT PDF</label><input id="sourceFind" type="search" value="${esc(sourceQuery)}" placeholder="e.g. Example, theorem, variance" /></div></div><div id="sourceMatches"></div><div class="button-row" style="margin:10px 0"><button class="chip selected" data-sourcetab="pdf" id="sourceTabPdf">PDF VIEW</button><button class="chip" data-sourcetab="text" id="sourceTabText">EXTRACTED TEXT</button></div><div id="sourcePdfView"><iframe id="pdfFrame" title="Original course PDF" src="${uri}#page=${sourcePage}"></iframe></div><div id="sourceTextView" style="display:none"><div class="page-text" id="sourcePageText">${esc(val)}</div></div>`}
const calcFields={
'mean-z':[['xbar','Sample mean x̄',72],['n','Sample size n',36],['sigma','Known population SD σ',12]],
'mean-t':[['xbar','Sample mean x̄',20],['n','Sample size n',10],['s','Sample SD s',4]],
'proportion':[['x','Number of successes',45],['n','Sample size n',300]],
'diff-proportion':[['x1','Successes group 1',60],['n1','Sample size group 1',100],['x2','Successes group 2',40],['n2','Sample size group 2',100]],
'pooled':[['m1','Mean group 1',50],['s1','Sample SD group 1',5],['n1','Size group 1',10],['m2','Mean group 2',46],['s2','Sample SD group 2',5],['n2','Size group 2',10]],
'welch':[['m1','Mean group 1',40],['s1','Sample SD group 1',4],['n1','Size group 1',16],['m2','Mean group 2',36],['s2','Sample SD group 2',8],['n2','Size group 2',16]],
'known-two':[['m1','Mean group 1',80],['sigma1','Population SD group 1',10],['n1','Size group 1',25],['m2','Mean group 2',75],['sigma2','Population SD group 2',12],['n2','Size group 2',36]],
'paired':[['dbar','Mean of paired differences',2],['sd','SD of paired differences',.81649658],['n','Number of pairs',4]],
'variance':[['s2','Sample variance s²',4],['n','Sample size n',11]],
'variance-known':[['sum','Σ(xᵢ−μ)² (μ known)',2],['n','Sample size n',3]],
'ratio':[['s12','Sample variance s₁²',9],['n1','Size group 1',11],['s22','Sample variance s₂²',4],['n2','Size group 2',11]]};
const calcTitles={'mean-z':'Mean / known σ (z)','mean-t':'Mean / unknown σ (t)','proportion':'One proportion (z)','diff-proportion':'Two proportions (z)','pooled':'Two means / equal unknown variances','welch':'Two means / unequal unknown variances','known-two':'Two means / known σs','paired':'Paired mean differences (t)','variance':'One variance / unknown μ (χ²)','variance-known':'One variance / known μ (χ²)','ratio':'Ratio of variances (F)'};
function calculator(){return `${header('WORKED CALCULATION ENGINE','Confidence interval calculator.','Choose the correct case, enter known sample values and instantly compute the interval with a transparent substitution path. Critical values are computed numerically from standard distributions.')}<div class="control-panel" style="margin:21px 0 15px"><div class="section-kicker">FORMULA FINDER · ANSWER 3 QUESTIONS</div><p class="tip-line">Don't know which formula to use? Choose your parameter, study design and what is known. The suggestion will update automatically.</p><div class="control-grid"><div class="field"><label>What are you estimating?</label><select id="decisionParam"><option value="mean">Mean / average</option><option value="prop">Proportion / percentage</option><option value="var">Variance / spread</option></select></div><div class="field"><label>How many groups?</label><select id="decisionGroups"><option value="one">One group</option><option value="two">Two groups</option></select></div><div class="field"><label>What is known?</label><select id="decisionKnown"><option value="no">Population σ unknown (or μ unknown for variance)</option><option value="yes">Population σ known (or μ known for variance)</option></select></div><div class="field"><label>For two means, which design?</label><select id="decisionDesign"><option value="unequal">Independent · unequal / unspecified variances</option><option value="equal">Independent · equal variances</option><option value="paired">Paired observations</option></select></div></div><div id="decisionResult" class="source-note" style="margin-bottom:20px"></div><div class="thin-divider"></div><div class="field" style="max-width:650px"><label>SELECT QUESTION TYPE / ASSUMPTIONS</label><select id="calcMode">${Object.keys(calcTitles).map(k=>`<option value="${k}" ${calculatorMode===k?'selected':''}>${esc(calcTitles[k])}</option>`).join('')}</select></div><div class="control-grid" style="margin-top:22px" id="calcInputs">${calcFields[calculatorMode].map(([id,label,v])=>`<div class="field"><label>${esc(label)}</label><input type="number" step="any" id="cf_${id}" value="${v}" data-calc-input="1" /></div>`).join('')}<div class="field"><label>Confidence level</label><select id="calcConfidence"><option value=".90">90%</option><option value=".95" selected>95%</option><option value=".98">98%</option><option value=".99">99%</option></select></div></div><div class="button-row" style="margin-top:23px"><button class="btn" data-action="calculate">Calculate CI ↗</button><button class="btn secondary" data-action="calc-reset">Reset example</button></div></div><div id="calcResult" class="source-note">Choose a case, check the inputs and select <strong>Calculate CI</strong>.</div><div class="source-note"><strong>Assumptions:</strong> Normal-based formulas require independence, appropriate normal sampling assumptions or valid large-sample approximations. Proportion intervals here use the source handout's Wald normal approximation. Small or extreme proportions need more careful methods.</div>`}
function notFound(){return header('NOT FOUND','This chapter does not exist.','Use the sidebar to return to a lesson.')+`<button class="btn" data-go="home">Back home</button>`}
function render({keep=false}={}){const y=keep?window.scrollY:0;currentRoute=route();const [section,slug]=currentRoute.split('/');if(section!=='practice')clearInterval(quizTimer);let c;
switch(section){case 'home':c=home();break;case 'lesson':c=lesson(slug);break;case 'plan':c=plan();break;case 'labs':c=slug?lab(slug):labs();break;case 'practice':c=practice();break;case 'calculator':c=calculator();break;case 'formulas':c=formulas();break;case 'sources':c=header('OFFLINE FILES','PDF handouts are not published here.','The original university handouts are kept in your private, offline package. They are omitted from public hosting unless you have permission to redistribute them.');break;default:c=notFound()}
$('#mainContent').innerHTML=c;sidebar();$('#breadcrumb').textContent=section==='lesson'?(CH.find(z=>z.id===slug)?.title||'Lesson'):NAV.find(x=>x[0]===section)?.[2]||'Overview';if(!keep)window.scrollTo(0,0);else window.scrollTo(0,y);$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show');drawForRoute();if(section==='practice'&&state.quizMode==='mock'&&!state.quizSubmitted&&state.quizDeadline>Date.now())startTimer();else if(section==='practice'&&state.quizMode==='mock'&&!state.quizSubmitted&&state.quizDeadline&&state.quizDeadline<=Date.now()){state.quizSubmitted=true;save();render({keep:true})}}
// Precise probability numerical methods. CDF is lower-tail everywhere.
function logGamma(z){const p=[.99999999999980993,676.5203681218851,-1259.1392167224028,771.3234287776531,-176.6150291621406,12.507343278686905,-.13857109526572012,9.984369578019572e-6,1.5056327351493116e-7];if(z<.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-logGamma(1-z);z-=1;let x=p[0];for(let i=1;i<p.length;i++)x+=p[i]/(z+i);let t=z+7.5;return .5*Math.log(2*Math.PI)+(z+.5)*Math.log(t)-t+Math.log(x)}
function gammaP(a,x){if(x<=0)return 0;if(x<a+1){let sum=1/a,term=sum;for(let n=1;n<10000;n++){term*=x/(a+n);sum+=term;if(Math.abs(term)<Math.abs(sum)*1e-14)break}return clamp(sum*Math.exp(-x+a*Math.log(x)-logGamma(a)),0,1)}let b=x+1-a,c=1e30,d=1/b,h=d;for(let i=1;i<10000;i++){let an=-i*(i-a);b+=2;d=an*d+b;if(Math.abs(d)<1e-30)d=1e-30;c=b+an/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;let del=d*c;h*=del;if(Math.abs(del-1)<3e-14)break}return clamp(1-Math.exp(-x+a*Math.log(x)-logGamma(a))*h,0,1)}
function betacf(a,b,x){let qab=a+b,qap=a+1,qam=a-1,c=1,d=1-qab*x/qap;if(Math.abs(d)<1e-30)d=1e-30;d=1/d;let h=d;for(let m=1;m<=400;m++){let m2=2*m,aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<1e-30)d=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<1e-30)d=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;let del=d*c;h*=del;if(Math.abs(del-1)<3e-14)break}return h}
function betai(x,a,b){if(x<=0)return 0;if(x>=1)return 1;let bt=Math.exp(logGamma(a+b)-logGamma(a)-logGamma(b)+a*Math.log(x)+b*Math.log1p(-x));return clamp(x<(a+1)/(a+b+2)?bt*betacf(a,b,x)/a:1-bt*betacf(b,a,1-x)/b,0,1)}
function normalCDF(x){const sign=x<0?-1:1,z=Math.abs(x)/Math.sqrt(2),t=1/(1+.3275911*z);let erf=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-z*z);return clamp(.5*(1+sign*erf),0,1)}
function distCDF(kind,x,df1=8,df2=12){if(kind==='normal')return normalCDF(x);if(kind==='t'){let q=betai(df1/(df1+x*x),df1/2,.5);return x>=0?1-q/2:q/2}if(x<=0)return 0;if(kind==='chi')return gammaP(df1/2,x/2);if(kind==='f')return betai(df1*x/(df1*x+df2),df1/2,df2/2);return NaN}
function distPDF(kind,x,df1=8,df2=12){if(kind==='normal')return Math.exp(-x*x/2)/Math.sqrt(2*Math.PI);if(kind==='t')return Math.exp(logGamma((df1+1)/2)-logGamma(df1/2)) / Math.sqrt(df1*Math.PI)*Math.pow(1+x*x/df1,-(df1+1)/2);if(x<=0)return 0;if(kind==='chi')return Math.exp((df1/2-1)*Math.log(x)-x/2-(df1/2)*Math.log(2)-logGamma(df1/2));if(kind==='f')return Math.exp((df1/2)*Math.log(df1/df2)+(df1/2-1)*Math.log(x)-((df1+df2)/2)*Math.log1p(df1*x/df2)-(logGamma(df1/2)+logGamma(df2/2)-logGamma((df1+df2)/2)));return 0}
function quant(kind,p,df1,df2){p=clamp(p,1e-10,1-1e-10);let lo=(kind==='normal'||kind==='t')?-40:0,hi=(kind==='normal'||kind==='t')?40:2;if(lo===0){while(distCDF(kind,hi,df1,df2)<p&&hi<1e12)hi*=2}for(let i=0;i<95;i++){let mid=(lo+hi)/2;if(distCDF(kind,mid,df1,df2)<p)lo=mid;else hi=mid}return (lo+hi)/2}
function clamp(x,a,b){return Math.min(b,Math.max(a,x))}
function fmt(x,d=4){return Number.isFinite(x)?(+x.toFixed(d)).toLocaleString('en-US',{maximumFractionDigits:d}):'undefined'}
function calculate(){let get=id=>Number($('#cf_'+id)?.value),n=get('n'),n1=get('n1'),n2=get('n2'),cf=Number($('#calcConfidence').value),a=1-cf,z=quant('normal',1-a/2),m=calculatorMode,estimate,se,crit=z,df=null,method='',details=[],low,high;
const val=Object.fromEntries(calcFields[m].map(([id])=>[id,get(id)]));if(Object.values(val).some(v=>!Number.isFinite(v))){$('#calcResult').innerHTML='Enter valid numbers in all fields.';return}
if(['mean-z','mean-t','proportion','variance','variance-known','paired'].includes(m)&&(!Number.isInteger(n)||n<1)){return calcError('n must be a positive integer.')}
if(['diff-proportion','pooled','welch','known-two','ratio'].includes(m)&&(!Number.isInteger(n1)||!Number.isInteger(n2)||n1<1||n2<1)){return calcError('Group sizes must be positive integers.')}
switch(m){
case 'mean-z':if(val.sigma<0)return calcError('σ must be nonnegative.');estimate=val.xbar;se=val.sigma/Math.sqrt(n);method='Normal z interval';details=[`SE = ${fmt(val.sigma)}/√${n} = ${fmt(se)}`];break;
case 'mean-t':if(n<2||val.s<0)return calcError('n≥2 and s≥0 required.');estimate=val.xbar;se=val.s/Math.sqrt(n);df=n-1;crit=quant('t',1-a/2,df);method='Student t interval';details=[`df=n−1=${df}`,`SE=s/√n=${fmt(se)}`];break;
case 'proportion':if(val.x<0||val.x>n||!Number.isInteger(val.x))return calcError('Successes must be an integer from 0 to n.');estimate=val.x/n;se=Math.sqrt(estimate*(1-estimate)/n);method='Wald normal proportion interval';details=[`p̂=${val.x}/${n}=${fmt(estimate)}`,`SE=√[p̂(1−p̂)/n]=${fmt(se)}`];break;
case 'diff-proportion':if(n1<1||n2<1||val.x1<0||val.x1>n1||val.x2<0||val.x2>n2||!Number.isInteger(val.x1)||!Number.isInteger(val.x2))return calcError('Each success count must be an integer between 0 and that sample size.');let p1=val.x1/n1,p2=val.x2/n2;estimate=p1-p2;se=Math.sqrt(p1*(1-p1)/n1+p2*(1-p2)/n2);method='Unpooled two-proportion Wald interval';details=[`p̂₁=${fmt(p1)}, p̂₂=${fmt(p2)}`,`SE=${fmt(se)}`];break;
case 'pooled':if(n1<2||n2<2||val.s1<0||val.s2<0)return calcError('n₁,n₂≥2; sample SDs nonnegative.');df=n1+n2-2;let sp2=((n1-1)*val.s1**2+(n2-1)*val.s2**2)/df;estimate=val.m1-val.m2;se=Math.sqrt(sp2*(1/n1+1/n2));crit=quant('t',1-a/2,df);method='Pooled two-sample t interval';details=[`Sₚ²=${fmt(sp2)}, df=${df}`,`SE=Sₚ√(1/n₁+1/n₂)=${fmt(se)}`];break;
case 'welch':if(n1<2||n2<2||val.s1<0||val.s2<0)return calcError('n₁,n₂≥2; sample SDs nonnegative.');let v1=val.s1**2/n1,v2=val.s2**2/n2;df=(v1+v2)**2/(v1*v1/(n1-1)+v2*v2/(n2-1));if(!Number.isFinite(df))return calcError('At least one sample SD must be positive.');estimate=val.m1-val.m2;se=Math.sqrt(v1+v2);crit=quant('t',1-a/2,df);method='Welch two-sample t interval';details=[`SE=√(S₁²/n₁+S₂²/n₂)=${fmt(se)}`,`Welch df≈${fmt(df,2)}`];break;
case 'known-two':if(n1<1||n2<1||val.sigma1<0||val.sigma2<0)return calcError('Valid sizes and nonnegative SDs required.');estimate=val.m1-val.m2;se=Math.sqrt(val.sigma1**2/n1+val.sigma2**2/n2);method='Known-population-SDs z interval';details=[`SE=√(σ₁²/n₁+σ₂²/n₂)=${fmt(se)}`];break;
case 'paired':if(n<2||val.sd<0)return calcError('n≥2 and SD≥0.');estimate=val.dbar;se=val.sd/Math.sqrt(n);df=n-1;crit=quant('t',1-a/2,df);method='Paired differences t interval';details=[`df=${df}`,`SE=Sᴅ/√n=${fmt(se)}`];break;
case 'variance':if(n<2||val.s2<0)return calcError('n≥2; variance≥0.');df=n-1;let A=(n-1)*val.s2;low=A/quant('chi',1-a/2,df);high=A/quant('chi',a/2,df);method='Normal-population chi-square CI for variance';details=[`df=n−1=${df}`,`A=(n−1)S²=${fmt(A)}`,`Lower=A/χ²(${fmt(1-a/2,4)},df); Upper=A/χ²(${fmt(a/2,4)},df)`];break;
case 'variance-known':if(val.sum<0)return calcError('Sum of squares must be nonnegative.');df=n;low=val.sum/quant('chi',1-a/2,df);high=val.sum/quant('chi',a/2,df);method='Known-μ chi-square CI for variance';details=[`df=n=${df}`,`A=Σ(x−μ)²=${fmt(val.sum)}`];break;
case 'ratio':if(n1<2||n2<2||val.s12<=0||val.s22<=0)return calcError('n₁,n₂≥2; variances positive.');let r=val.s12/val.s22,df1=n1-1,df2=n2-1;low=r/quant('f',1-a/2,df1,df2);high=r/quant('f',a/2,df1,df2);method='F interval for variance ratio';details=[`Observed r=S₁²/S₂²=${fmt(r)}`,`df₁=${df1}, df₂=${df2}`,`Lower=r/F(${fmt(1-a/2,4)}); Upper=r/F(${fmt(a/2,4)})`];break;
}if(!Number.isFinite(low)||!Number.isFinite(high)){let me=crit*se;low=estimate-me;high=estimate+me;details.push(`Critical=${fmt(crit,5)}`,`Margin=${fmt(crit,5)}×${fmt(se)}=${fmt(me)}`,`${fmt(estimate)}±${fmt(me)}`)}
if(!(Number.isFinite(low)&&Number.isFinite(high)))return calcError('Inputs caused an undefined result. Check the model/values.');
let caution=(m==='proportion'||m==='diff-proportion')&&(low<0||high>1)?' Caution: Wald intervals can exceed valid probability bounds; consider a more appropriate method for inference.':'';
$('#calcResult').innerHTML=`<div class="eyebrow">COMPUTED ${fmt(cf*100,0)}% CONFIDENCE INTERVAL</div><h2 style="font-size:clamp(26px,4vw,39px);letter-spacing:-1px;margin:15px 0">[${fmt(low,5)}, ${fmt(high,5)}]</h2><div class="tip-line"><strong style="color:var(--text)">${esc(method)}</strong>${esc(caution)}</div><div class="thin-divider"></div><div class="eyebrow">SUBSTITUTION AND STEPS</div>${details.map((d,i)=>`<p class="tip-line">${i+1}. ${esc(d)}</p>`).join('')}<p class="tip-line">Assumed confidence ${fmt(cf*100,1)}% with α=${fmt(a,4)}. Interpretation: under repeated sampling, intervals constructed by this procedure cover the fixed true parameter at approximately this rate under model assumptions.</p>`;
}
function updateDecision(){let p=$('#decisionParam')?.value,g=$('#decisionGroups')?.value,k=$('#decisionKnown')?.value,d=$('#decisionDesign')?.value;if(!p)return;let type=p==='mean'?(g==='one'?(k==='yes'?'mean-z':'mean-t'):(d==='paired'?'paired':k==='yes'?'known-two':d==='equal'?'pooled':'welch')):p==='prop'?(g==='one'?'proportion':'diff-proportion'):(g==='one'?(k==='yes'?'variance-known':'variance'):'ratio');let reason=p==='mean'?(g==='one'?'One population mean: known SD means z; unknown SD normally means t.':d==='paired'?'Paired before/after observations become one sample of differences.':'Independent means require a known-SD z interval, or appropriate pooled/Welch t interval.'):p==='prop'?'Proportion confidence intervals use normal approximations if the relevant success/failure counts are adequate.':'Population variance confidence intervals use χ²; the ratio of two variances uses F under normality.';$('#decisionResult').innerHTML=`<strong>Recommended: ${esc(calcTitles[type])}</strong><p class="tip-line">${esc(reason)}</p><button class="btn small" data-recommend="${type}">Use this method ↗</button>`}
function calcError(message){$('#calcResult').innerHTML=`<strong>Input error:</strong> ${esc(message)}`}
function searchResults(value){let q=value.trim().toLocaleLowerCase();let ranked=CH.map((c,i)=>({c,i,score:!q?1:(c.title.toLowerCase().includes(q)?10:0)+(c.summary.toLowerCase().includes(q)?3:0)+c.concepts.filter(z=>(z.h+' '+z.b+' '+z.f).toLowerCase().includes(q)).length*2})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,18);$('#searchResults').innerHTML=ranked.length?ranked.map(({c,i})=>`<button class="search-result" data-go="lesson/${c.id}"><span class="paper-icon">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.tag)} · ${esc(c.summary.slice(0,100))}</small></div><span class="sr-arrow">↗</span></button>`).join(''):'<p class="tip-line" style="padding:17px">No topic found. Try a mathematical symbol or English term.</p>'}
function canvasCtx(canvas){if(!canvas)return null;let box=canvas.getBoundingClientRect(),w=Math.max(280,box.width),h=Math.max(140,box.height),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);let ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w,h}}
function palette(){let css=getComputedStyle(document.body);return {fg:css.getPropertyValue('--text').trim(),muted:css.getPropertyValue('--muted').trim(),bg:css.getPropertyValue('--bg').trim(),border:css.getPropertyValue('--border').trim(),isDark:document.body.dataset.theme==='dark'}}
function line(ctx,x1,y1,x2,y2,color,width=1,dash=[]){ctx.beginPath();ctx.setLineDash(dash);ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();ctx.setLineDash([])}
function label(ctx,txt,x,y,color,size=10,align='left'){ctx.fillStyle=color;ctx.font=`${size}px Inter, system-ui,sans-serif`;ctx.textAlign=align;ctx.fillText(txt,x,y)}
function plotCommon(ctx,w,h,xmin,xmax,ymax,func,threshold=NaN,{fillUnder=true}={}){let pal=palette(),ml=51,mr=20,mt=20,mb=43,pw=w-ml-mr,ph=h-mt-mb;let X=x=>ml+(x-xmin)/(xmax-xmin)*pw,Y=y=>h-mb-y/ymax*ph;ctx.clearRect(0,0,w,h);for(let i=0;i<=4;i++){let yy=mt+i*ph/4;line(ctx,ml,yy,w-mr,yy,pal.border,.6)}line(ctx,ml,h-mb,w-mr,h-mb,pal.muted,1);for(let i=0;i<=6;i++){let x=xmin+(xmax-xmin)*i/6;line(ctx,X(x),h-mb,X(x),h-mb+4,pal.muted,.7);label(ctx,fmt(x,1),X(x),h-17,pal.muted,10,'center')}
if(fillUnder&&Number.isFinite(threshold)){ctx.beginPath();ctx.moveTo(X(xmin),Y(0));for(let i=0;i<=500;i++){let x=xmin+(Math.min(xmax,threshold)-xmin)*i/500;if(x<xmin)continue;ctx.lineTo(X(x),Y(Math.max(0,Math.min(ymax,func(x)))))}ctx.lineTo(X(Math.min(xmax,Math.max(xmin,threshold))),Y(0));ctx.closePath();ctx.fillStyle=pal.isDark?'rgba(255,255,255,.18)':'rgba(0,0,0,.14)';ctx.fill()}
ctx.beginPath();for(let i=0;i<=650;i++){let x=xmin+(xmax-xmin)*i/650,y=Y(Math.max(0,Math.min(ymax,func(x))));if(i===0)ctx.moveTo(X(x),y);else ctx.lineTo(X(x),y)}ctx.strokeStyle=pal.fg;ctx.lineWidth=2.5;ctx.stroke();if(Number.isFinite(threshold)&&threshold>=xmin&&threshold<=xmax){line(ctx,X(threshold),mt,X(threshold),h-mb,pal.fg,1,[5,5]);let z=Math.max(0,Math.min(ymax,func(threshold)));ctx.beginPath();ctx.arc(X(threshold),Y(z),4.5,0,Math.PI*2);ctx.fillStyle=pal.fg;ctx.fill();label(ctx,'x = '+fmt(threshold,2),X(threshold)+7,mt+15,pal.fg,10)}return {X,Y,ml,mr,mt,mb,pw,ph}}
function drawDist(){let canvas=$('#distCanvas');if(!canvas)return;let d=canvasCtx(canvas),kind=$('#distKind').value,df1=+$(' #distDf1'.trim()).value,df2=+$('#distDf2').value;$('#df1label').textContent=df1;$('#df2label').textContent=df2;let threshold=+$('#distThreshold').value;if(kind==='normal'||kind==='t'){$('#distThreshold').min=-3.5;$('#distThreshold').max=4.5}else{$('#distThreshold').min=0;$('#distThreshold').max=kind==='chi'?Math.max(6,df1*2):8;if(threshold<0){threshold=0;$('#distThreshold').value=0}}$('#thresholdLabel').textContent=fmt(threshold,2);let xmin=kind==='normal'||kind==='t'?-4.3:0,xmax=kind==='normal'||kind==='t'?4.3:kind==='chi'?Math.max(8,df1+5*Math.sqrt(2*df1)):8;let func=x=>distPDF(kind,x,df1,df2),sample=[];for(let i=0;i<=450;i++){let x=xmin+(xmax-xmin)*i/450,y=func(x);if(Number.isFinite(y))sample.push(y)}let ymax=Math.max(...sample,0.15)*1.21;plotCommon(d.ctx,d.w,d.h,xmin,xmax,ymax,func,threshold);let p=distCDF(kind,threshold,df1,df2);$('#distLeft').textContent=fmt(p,6);$('#distRight').textContent=fmt(1-p,6)}
let surfaceState={yaw:35*Math.PI/180,elev:38*Math.PI/180,spread:1,height:1,drag:false,lastX:0,lastY:0};
function draw3D(canvas,hero=false){if(!canvas)return;let z=canvasCtx(canvas);if(!z)return;let {ctx,w,h}=z,pal=palette(),yaw=surfaceState.yaw,elev=surfaceState.elev,spread=surfaceState.spread,height=surfaceState.height;ctx.clearRect(0,0,w,h);const sc=Math.min(w/8.2,h/7.2),cenY=h*.67;function proj(x,y,v){let xr=x*Math.cos(yaw)-y*Math.sin(yaw),yr=x*Math.sin(yaw)+y*Math.cos(yaw);return [w/2+xr*sc,cenY+yr*sc*Math.sin(elev)-v*sc*1.45*Math.cos(elev)]}let gridN=hero?20:32,range=3,quads=[];const H=(x,y)=>height*Math.exp(-(x*x+y*y)/(2*spread*spread));
for(let i=0;i<gridN;i++)for(let j=0;j<gridN;j++){let x=-range+i*2*range/gridN,y=-range+j*2*range/gridN,dx=2*range/gridN,dy=dx;let pts=[[x,y],[x+dx,y],[x+dx,y+dy],[x,y+dy]].map(([px,py])=>proj(px,py,H(px,py)));let dep=(x+.5*dx)*Math.sin(yaw)+(y+.5*dy)*Math.cos(yaw);let v=H(x+dx/2,y+dy/2);quads.push({pts,dep,v})}
quads.sort((a,b)=>b.dep-a.dep);let color=pal.isDark?'255,255,255':'0,0,0';quads.forEach(q=>{ctx.beginPath();ctx.moveTo(...q.pts[0]);q.pts.slice(1).forEach(p=>ctx.lineTo(...p));ctx.closePath();ctx.fillStyle=`rgba(${color},${(hero?.018:.04)+(q.v/Math.max(height,0.01))*(hero?.08:.13)})`;ctx.fill();ctx.lineWidth=hero?.47:.6;ctx.strokeStyle=`rgba(${color},${(hero?.16:.24)+q.v/Math.max(height,.01)*(hero?.24:.30)})`;ctx.stroke()});
let a=proj(-3,0,0),b=proj(3,0,0),c=proj(0,-3,0),e=proj(0,3,0),base=proj(0,0,0),peak=proj(0,0,height);line(ctx,...a,...b,pal.muted,.8);line(ctx,...c,...e,pal.muted,.8);line(ctx,...base,...peak,pal.fg,.9,[3,5]);ctx.beginPath();ctx.arc(...peak,hero?3:4,0,2*Math.PI);ctx.fillStyle=pal.fg;ctx.fill();if(!hero){label(ctx,'X',...b.map((v,i)=>v+(i?10:10)),pal.muted);label(ctx,'Y',...e.map((v,i)=>v+(i?10:10)),pal.muted);label(ctx,'Joint density',w-16,21,pal.muted,10,'right')}}
let simSamples=[],simN=25,simConf=.95;const normalRandom=()=>{let u=1-Math.random(),v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)};
function addSample(k=1){simN=+$('#sampleN').value;simConf=+$('#sampleLevel').value;let z=quant('normal',(1+simConf)/2),se=1/Math.sqrt(simN);for(let i=0;i<k;i++){let mean=normalRandom()*se,half=z*se;simSamples.push({lo:mean-half,hi:mean+half,hit:mean-half<=0&&mean+half>=0})}drawSamples()}
function drawSamples(){let cv=$('#sampleCanvas');if(!cv)return;let {ctx,w,h}=canvasCtx(cv),p=palette();simN=+$('#sampleN').value;simConf=+$('#sampleLevel').value;$('#sampleNLabel').textContent=simN;$('#sampleTrials').textContent=simSamples.length;$('#sampleCoverage').textContent=simSamples.length?fmt(simSamples.filter(s=>s.hit).length/simSamples.length*100,1)+'%':'—';let maxn=36,list=simSamples.slice(-maxn),maxAbs=Math.max(.8,...list.map(s=>Math.max(Math.abs(s.lo),Math.abs(s.h))))*1.14;let X=x=>w/2+(x/maxAbs)*(w/2-43);line(ctx,X(0),20,X(0),h-30,p.fg,1.4,[7,5]);label(ctx,'true μ = 0',X(0)+8,17,p.fg,11);let top=32,spacing=(h-top-32)/Math.max(maxn,1);for(let i=0;i<list.length;i++){let s=list[i],y=top+(i+.5)*spacing,alpha=s.hit?1:.28;colorline(ctx,X(s.lo),y,X(s.hi),y,p,alpha,s.hit?2.4:2);ctx.beginPath();ctx.arc(X((s.lo+s.hi)/2),y,2,0,2*Math.PI);ctx.fillStyle=p.fg;ctx.globalAlpha=alpha;ctx.fill();ctx.globalAlpha=1}line(ctx,35,h-30,w-35,h-30,p.muted,.8);label(ctx,'− error',36,h-11,p.muted,10);label(ctx,'+ error',w-36,h-11,p.muted,10,'right');if(!list.length)label(ctx,'Draw samples to watch confidence intervals.',w/2,h/2,p.muted,13,'center')}
function colorline(ctx,x1,y1,x2,y2,p,a,lw){ctx.save();ctx.globalAlpha=a;line(ctx,x1,y1,x2,y2,p.fg,lw,a<1?[4,4]:[]);ctx.restore()}
function drawIntegral(){let cv=$('#integralCanvas');if(!cv)return;let {ctx,w,h}=canvasCtx(cv),p=palette(),b=+$('#integralBound').value,n=+$('#integralRects').value,kind=$('#integralFunction').value;$('#boundLabel').textContent=b.toFixed(1);$('#rectLabel').textContent=n;let fn=kind==='square'?x=>x*x:kind==='linear'?x=>2*x:x=>Math.exp(-x),exact=kind==='square'?b**3/3:kind==='linear'?b*b:1-Math.exp(-b),dx=b/n,sum=0;for(let i=0;i<n;i++)sum+=fn(i*dx)*dx;$('#integralApprox').textContent=fmt(sum,6);$('#integralExact').textContent=fmt(exact,6);let margin=38,xmin=0,xmax=b*1.06,ymax=Math.max(fn(b),fn(0)) *1.2+0.08;let X=x=>margin+x/xmax*(w-2*margin),Y=y=>h-margin-y/ymax*(h-2*margin);for(let i=0;i<=4;i++)line(ctx,margin,margin+(h-2*margin)/4*i,w-margin,margin+(h-2*margin)/4*i,p.border,.6);line(ctx,margin,h-margin,w-margin,h-margin,p.muted,1);for(let i=0;i<n;i++){let x=i*dx,y=fn(x),left=X(x),width=X(x+dx)-X(x);ctx.fillStyle=p.isDark?'rgba(255,255,255,.13)':'rgba(0,0,0,.12)';ctx.fillRect(left,Y(y),width,h-margin-Y(y));ctx.strokeStyle=p.isDark?'rgba(255,255,255,.30)':'rgba(0,0,0,.27)';ctx.strokeRect(left,Y(y),width,h-margin-Y(y))}ctx.beginPath();for(let i=0;i<=400;i++){let x=b*i/400;if(i===0)ctx.moveTo(X(x),Y(fn(x)));else ctx.lineTo(X(x),Y(fn(x)))}ctx.strokeStyle=p.fg;ctx.lineWidth=2.7;ctx.stroke();label(ctx,'0',margin,h-14,p.muted);label(ctx,'b = '+fmt(b,2),X(b),h-13,p.muted,11,'center');label(ctx,'f(x)',margin+7,26,p.fg,11);}
function drawMle(){let cv=$('#mleCanvas');if(!cv)return;let {ctx,w,h}=canvasCtx(cv),n=+$('#mleN').value,k=+$('#mleK').value;$('#mleK').max=n;if(k>n){k=n;$('#mleK').value=k}$('#mleNLabel').textContent=n;$('#mleKLabel').textContent=k;let phat=k/n,maxLog=k*(phat>0?Math.log(phat):0)+(n-k)*(phat<1?Math.log(1-phat):0),f=p=>{if((p===0&&k>0)||(p===1&&k<n))return 0;let logval=k*(p>0?Math.log(p):0)+(n-k)*(p<1?Math.log(1-p):0);return Math.exp(logval-maxLog)};plotCommon(ctx,w,h,0,1,1.15,f,phat,{fillUnder:false});$('#mleEstimate').textContent='p̂ = '+fmt(phat,3);$('#mleMeaning').textContent=`${k} successes of ${n} observations suggest p̂ = ${fmt(k/n,3)} by maximizing L(p)∝pᵏ(1−p)ⁿ⁻ᵏ.`}
function drawForRoute(){if(currentRoute==='calculator')updateDecision();if(currentRoute==='home'){let el=$('#heroCanvas');if(el)draw3D(el,true)}if(currentRoute==='labs/normal')drawDist();if(currentRoute==='labs/3d'){update3dControls();draw3D($('#surfaceCanvas'));init3DDrag()}if(currentRoute==='labs/sampling')drawSamples();if(currentRoute==='labs/integral')drawIntegral();if(currentRoute==='labs/mle')drawMle();}
function update3dControls(){surfaceState.spread=+$('#spreadRange').value;surfaceState.height=+$('#heightRange').value;surfaceState.yaw=+$('#rotationRange').value*Math.PI/180;surfaceState.elev=+$('#elevationRange').value*Math.PI/180;$('#spreadLabel').textContent=surfaceState.spread.toFixed(2);$('#heightLabel').textContent=surfaceState.height.toFixed(2);$('#rotationLabel').textContent=Math.round(surfaceState.yaw*180/Math.PI)+'°';$('#elevationLabel').textContent=Math.round(surfaceState.elev*180/Math.PI)+'°'}
function init3DDrag(){let cv=$('#surfaceCanvas');if(!cv)return;cv.onpointerdown=e=>{surfaceState.drag=true;surfaceState.lastX=e.clientX;surfaceState.lastY=e.clientY;cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(!surfaceState.drag)return;let dx=e.clientX-surfaceState.lastX,dy=e.clientY-surfaceState.lastY;surfaceState.lastX=e.clientX;surfaceState.lastY=e.clientY;surfaceState.yaw+=dx*.011;surfaceState.elev=clamp(surfaceState.elev-dy*.007,.12,1.35);$('#rotationRange').value=Math.round(((surfaceState.yaw*180/Math.PI)%360+360)%360);$('#elevationRange').value=Math.round(surfaceState.elev*180/Math.PI);update3dControls();draw3D(cv)};cv.onpointerup=cv.onpointercancel=()=>surfaceState.drag=false}
async function loadSources(){try{let resp=await fetch('source-pages.json');if(!resp.ok)throw Error(resp.statusText);sourceFiles=await resp.json();if(route()==='sources')render({keep:true})}catch(e){console.warn('Could not load source index',e);toast('PDF handouts are offline-only.')}}
function sourceSelection(i){activeSource=i;sourcePage=1;sourceQuery='';go('sources');render({keep:true});document.getElementById('sourceView')?.scrollIntoView({behavior:'smooth',block:'start'})}
function sourceSearch(q){sourceQuery=q;let s=sourceFiles[activeSource];if(!s)return;let target=$('#sourceMatches');if(!q.trim()){target.innerHTML='';return}let matches=[];s.pages.forEach((page,j)=>{let pos=page.toLowerCase().indexOf(q.toLowerCase());if(pos>=0)matches.push({page:j+1,excerpt:page.slice(Math.max(0,pos-55),Math.min(page.length,pos+100)).replace(/\s+/g,' ')})});target.innerHTML=`<div class="tip-line">${matches.length} matching page(s): ${matches.slice(0,25).map(r=>`<button class="chip" data-jumppage="${r.page}" title="${esc(r.excerpt)}">Page ${r.page} ↗</button>`).join('')||'None found'}</div>`}
function modal(open){$('#searchModal').classList.toggle('open',open);$('#searchModal').setAttribute('aria-hidden',String(!open));if(open){$('#globalSearch').value='';searchResults('');$('#globalSearch').focus()}}
function exportProgress(){let body=JSON.stringify({format:'PCG_STATLAB_V1',exportedAt:new Date().toISOString(),state},null,2);let b=new Blob([body],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='pcg-statlab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function handleAction(name){switch(name){case 'print':window.print();break;case 'new-quiz':newQuiz();break;case 'reset-quiz':state.quizAnswers={};state.quizSubmitted=false;state.quizDeadline=0;save();render({keep:true});break;case 'submit-quiz':state.quizSubmitted=true;clearInterval(quizTimer);save();render({keep:true});break;case 'calculate':calculate();break;case 'calc-reset':render({keep:true});toast('Example inputs restored');break;case 'sample-one':addSample(1);break;case 'sample-100':addSample(100);break;case 'sample-clear':simSamples=[];drawSamples();break;case 'export-progress':exportProgress();break;case 'reset-progress':if(confirm('Reset study progress, notes and quiz responses? If cloud sync is active, this reset will also sync to your account.')){state={...defaults};save();render();toast('Local progress cleared')}break}}
function launchEvents(){document.addEventListener('click',e=>{let el=e.target.closest('[data-go],[data-action],[data-bookmark],[data-complete],[data-qchoice],[data-opensource],[data-source],[data-quizmode],[data-scroll],[data-sourcetab],[data-jumppage],[data-recommend]');if(!el)return;if(el.dataset.go){modal(false);go(el.dataset.go);return}if(el.dataset.recommend){calculatorMode=el.dataset.recommend;render({keep:true});toast('Selected '+calcTitles[calculatorMode]);return}if(el.dataset.action){handleAction(el.dataset.action);return}if(el.dataset.bookmark){let id=el.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render({keep:true});toast(state.bookmarks.includes(id)?'Bookmarked chapter':'Bookmark removed');return}if(el.dataset.complete){let id=el.dataset.complete;state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];save();render({keep:true});toast(state.completed.includes(id)?'Chapter completed ✓':'Chapter reopened');return}if(el.dataset.qchoice!==undefined){let idx=Number(el.dataset.qchoice),choice=Number(el.dataset.choice),inline=el.dataset.inline==='1',key=(inline?'lesson:':'practice:')+idx;if(inline)state.lessonAnswers[key]=choice;else if(!state.quizSubmitted)state.quizAnswers[key]=choice;save();render({keep:true});return}if(el.dataset.quizmode){state.quizMode=el.dataset.quizmode;state.quizItems=[];state.quizAnswers={};state.quizSubmitted=false;state.quizDeadline=0;clearInterval(quizTimer);save();render({keep:true});return}if(el.dataset.source){let i=sourceFiles.findIndex(f=>f.file===el.dataset.source);if(i>=0){activeSource=i;sourcePage=1;sourceQuery='';go('sources')}else{go('sources')}return}if(el.dataset.opensource!==undefined){sourceSelection(+el.dataset.opensource);return}if(el.dataset.jumppage){sourcePage=+el.dataset.jumppage;render({keep:true});return}if(el.dataset.sourcetab){let pdf=el.dataset.sourcetab==='pdf';$('#sourcePdfView').style.display=pdf?'block':'none';$('#sourceTextView').style.display=pdf?'none':'block';$('#sourceTabPdf').classList.toggle('selected',pdf);$('#sourceTabText').classList.toggle('selected',!pdf);return}if(el.dataset.scroll){e.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return}});
document.addEventListener('input',e=>{let id=e.target.id;if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save()}if(id==='formulaFilter')$('#formulaRows').innerHTML=makeFormulaRows(e.target.value);if(id==='sourceFind')sourceSearch(e.target.value);if(['distDf1','distDf2','distThreshold'].includes(id))drawDist();if(['spreadRange','heightRange','rotationRange','elevationRange'].includes(id)){update3dControls();draw3D($('#surfaceCanvas'))}if(['sampleN'].includes(id)){simSamples=[];drawSamples()}if(['integralBound','integralRects'].includes(id))drawIntegral();if(['mleN','mleK'].includes(id))drawMle()});
document.addEventListener('change',e=>{let id=e.target.id;if(id==='importProgress'){let file=e.target.files?.[0];if(!file)return;file.text().then(raw=>{let obj=JSON.parse(raw);if(obj.format!=='PCG_STATLAB_V1'||!obj.state||!Array.isArray(obj.state.completed))throw Error('Not a PCG STATLAB backup');let allowed=new Set(CH.map(c=>c.id));state={...defaults,...obj.state,completed:obj.state.completed.filter(id=>allowed.has(id)),bookmarks:(obj.state.bookmarks||[]).filter(id=>allowed.has(id))};save();render();toast('Progress imported successfully')}).catch(err=>toast('Import failed: '+err.message));return}if(['decisionParam','decisionGroups','decisionKnown','decisionDesign'].includes(id))updateDecision();if(id==='distKind')drawDist();if(id==='sampleLevel'){simSamples=[];drawSamples()}if(id==='integralFunction')drawIntegral();if(id==='calcMode'){calculatorMode=e.target.value;render({keep:true})}if(id==='sourcePageSelect'){sourcePage=+e.target.value;render({keep:true})}});
$('#searchBtn').onclick=()=>modal(true);$('#closeSearch').onclick=()=>modal(false);$('#searchModal').onclick=e=>{if(e.target.id==='searchModal')modal(false)};$('#globalSearch').oninput=e=>searchResults(e.target.value);
$('#themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.body.dataset.theme=state.theme;save();drawForRoute()};$('#focusBtn').onclick=()=>{state.focus=!state.focus;document.body.classList.toggle('focus',state.focus);save();setTimeout(drawForRoute,180)};$('#menuBtn').onclick=()=>{$('#sidebar').classList.add('open');$('#sidebarScrim').classList.add('show')};$('#sidebarScrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')};
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();modal(true)}if(e.key==='Escape')modal(false)});window.addEventListener('hashchange',()=>render());let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(drawForRoute,100)})}
function init(){document.body.dataset.theme=state.theme==='light'?'light':'dark';document.body.classList.toggle('focus',!!state.focus);launchEvents();render()}
window.PCG_STATLAB_BRIDGE={getState:()=>JSON.parse(JSON.stringify(state)),applyState:(next)=>{state={...defaults,...next};try{localStorage.setItem('PCG_STATLAB_STATE',JSON.stringify(state))}catch(_){};render();}};
init();
